SELECT FROM () session_resource_files WHERE kind = 'file' AND deleted_at IS NULL AND expires_at <= now() AND (workspace_uuid, session_uuid) IN ( SELECT workspace_uuid, session_uuid FROM filestore_filesystems WHERE uuid IN
#{filesystemUUID}
) ORDER BY expires_at, uuid LIMIT #{params.Limit}

SELECT uuid, external_id, organization_uuid, workspace_uuid, session_uuid,
    code_session_uuid, created_by_api_key_uuid, created_at, updated_at, deleted_at
FROM filestore_filesystems
WHERE workspace_uuid = #{workspaceUUID}
    AND uuid = #{filesystemUUID}

SELECT 
FROM () session_resource_files
WHERE workspace_uuid = #{params.WorkspaceUUID}
    AND session_uuid = #{params.SessionUUID}
    AND kind = 'file' AND deleted_at IS NULL
ORDER BY uuid
LIMIT #{params.Limit}

SELECT EXISTS (
    SELECT 1 FROM session_resources
    WHERE workspace_uuid = #{workspaceUUID} AND session_uuid = #{sessionUUID}
        AND resource_type = 'file' AND deleted_at IS NULL
) AS files_remain

mapper.update:
UPDATE files file SET deleted_at = #{params.RetiredAt}
WHERE file.workspace_uuid = #{params.WorkspaceUUID} AND file.deleted_at IS NULL
    AND file.uuid IN (
        SELECT resource.file_uuid FROM session_resources resource
        WHERE resource.workspace_uuid = #{params.WorkspaceUUID}
            AND resource.session_uuid = #{params.SessionUUID}
            AND resource.resource_type = 'skill_archive'
            AND resource.file_uuid IS NOT NULL AND resource.deleted_at IS NULL
    )

UPDATE session_resources
SET deleted_at = #{params.RetiredAt}, updated_at = #{params.RetiredAt}
WHERE workspace_uuid = #{params.WorkspaceUUID} AND session_uuid = #{params.SessionUUID}
    AND resource_type IN ('directory', 'skill_archive') AND deleted_at IS NULL

