SELECT status FROM jobs
WHERE external_id = #{params.JobExternalID} AND type = #{params.JobType}
    AND payload->>'workspace_uuid' = CAST(#{params.WorkspaceUUID} AS text)

mapper.update:
UPDATE jobs
SET status = 'canceled', locked_by = NULL, locked_until = NULL, updated_at = now()
WHERE external_id = #{params.JobExternalID} AND type = #{params.JobType}
    AND status IN ('pending', 'retry')
    AND payload->>'workspace_uuid' = CAST(#{params.WorkspaceUUID} AS text)
    AND payload->>'bucket' = #{params.Bucket}
    AND payload->>'key' = #{params.Key}
    AND COALESCE(payload->>'version_id', '') = #{params.VersionID}

