SELECT 
FROM () session_resource_files
WHERE workspace_uuid = #{params.WorkspaceUUID} AND session_uuid = #{params.SessionUUID}
    AND kind = 'file' AND deleted_at IS NULL AND expires_at <= now()
    AND (
        path = #{params.RootPath}
        OR left(path, char_length(#{params.RootPath}) + 1) = #{params.RootPath} || '/'
    )
ORDER BY id
